UCharacterMovementComponent::UCharacterMovementComponent(const FObjectInitializer& ObjectInitializer)
	: Super(ObjectInitializer)
{
	RandomStream.Initialize(FApp::bUseFixedSeed ? GetFName() : NAME_None);

	PostPhysicsTickFunction.bCanEverTick = true;
	PostPhysicsTickFunction.bStartWithTickEnabled = false;
	PostPhysicsTickFunction.SetTickFunctionEnable(false);
	PostPhysicsTickFunction.TickGroup = TG_PostPhysics;
	PostPhysicsTickFunction.bRunTransactionally = true;

	if (CharacterMovementCVars::AsyncCharacterMovement == 1)
	{
		PostPhysicsTickFunction.bStartWithTickEnabled = true;
		PostPhysicsTickFunction.SetTickFunctionEnable(true);

		PrePhysicsTickFunction.bCanEverTick = true;
		PrePhysicsTickFunction.bStartWithTickEnabled = true;
		PrePhysicsTickFunction.SetTickFunctionEnable(true);
		PrePhysicsTickFunction.TickGroup = TG_PrePhysics;
	}
	bDontFallBelowJumpZVelocityDuringJump = true;
	bApplyGravityWhileJumping = true;

	GravityScale = 1.f;
	GroundFriction = 8.0f;
	JumpZVelocity = 420.0f;
	JumpOffJumpZFactor = 0.5f;
	RotationRate = FRotator(0.f, 360.0f, 0.0f);

	SafeMoveUpdatedComponent( Delta, PawnRotation, true, Hit);
	if ( Hit.Time == 0.f )
	{
		// if we are stuck then try to side step
		FVector SideDelta = ProjectToGravityFloor(OldHitNormal + Hit.ImpactNormal).GetSafeNormal();
		if ( SideDelta.IsNearlyZero() )
		{
			if (HasCustomGravity())
			{
				const FVector GravityRelativeHitNormal = RotateWorldToGravity(OldHitNormal);
				SideDelta = RotateGravityToWorld(FVector(GravityRelativeHitNormal.Y, -GravityRelativeHitNormal.X, 0.f)).GetSafeNormal();
			}
			else
			{
				SideDelta = FVector(OldHitNormal.Y, -OldHitNormal.X, 0).GetSafeNormal();	
			}
		}
		SafeMoveUpdatedComponent( SideDelta, PawnRotation, true, Hit);
	}

	if ( bDitch || IsValidLandingSpot(UpdatedComponent->GetComponentLocation(), Hit) || Hit.Time == 0.f  )
	{
		remainingTime = 0.f;
		ProcessLanded(Hit, remainingTime, Iterations);
		return;
	}
	else if (GetPerchRadiusThreshold() > 0.f && Hit.Time == 1.f && GetGravitySpaceZ(OldHitImpactNormal) >= WalkableFloorZ)
	{
		// We might be in a virtual 'ditch' within our perch radius. This is rare.
		const FVector PawnLocation = UpdatedComponent->GetComponentLocation();
		const float ZMovedDist = FMath::Abs(GetGravitySpaceZ(PawnLocation - OldLocation));
		const float MovedDist2D = ProjectToGravityFloor(PawnLocation - OldLocation).Size();
		if (ZMovedDist <= 0.2f * timeTick && MovedDist2D <= 4.f * timeTick)
		{
			FVector GravityRelativeVelocity = RotateWorldToGravity(Velocity);
			GravityRelativeVelocity.X += 0.25f * GetMaxSpeed() * (RandomStream.FRand() - 0.5f);
			GravityRelativeVelocity.Y += 0.25f * GetMaxSpeed() * (RandomStream.FRand() - 0.5f);
			GravityRelativeVelocity.Z = FMath::Max<float>(JumpZVelocity * 0.25f, 1.f);
			Velocity = RotateGravityToWorld(GravityRelativeVelocity);
			Delta = Velocity * timeTick;
			SafeMoveUpdatedComponent(Delta, PawnRotation, true, Hit);
		}
	}
}

bool UCharacterMovementComponent::IsValidLandingSpot(const FVector& CapsuleLocation, const FHitResult& Hit) const
{
	if (!Hit.bBlockingHit)
	{
		return false;
	}

	// Skip some checks if penetrating. Penetration will be handled by the FindFloor call (using a smaller capsule)
	if (!Hit.bStartPenetrating)
	{
		// Reject unwalkable floor normals.
		if (!IsWalkable(Hit))
		{
			return false;
		}

		float PawnRadius, PawnHalfHeight;
		CharacterOwner->GetCapsuleComponent()->GetScaledCapsuleSize(PawnRadius, PawnHalfHeight);

		// Reject hits that are above our lower hemisphere (can happen when sliding down a vertical surface).
		const FVector::FReal LowerHemisphereZ = GetGravitySpaceZ(Hit.Location) - PawnHalfHeight + PawnRadius;
		if (GetGravitySpaceZ(Hit.ImpactPoint) >= LowerHemisphereZ)
		{
			return false;
		}

		// Reject hits that are barely on the cusp of the radius of the capsule
		if (!IsWithinEdgeTolerance(Hit.Location, Hit.ImpactPoint, PawnRadius))
		{
			return false;
		}
	}
	else
	{
		// Penetrating
		if (GetGravitySpaceZ(Hit.Normal) < UE_KINDA_SMALL_NUMBER)
		{
			// Normal is nearly horizontal or downward, that's a penetration adjustment next to a vertical or overhanging wall. Don't pop to the floor.
			return false;
		}
	}

	FFindFloorResult FloorResult;
	FindFloor(CapsuleLocation, FloorResult, false, &Hit);

